<div class="erp-page-head"><form class="erp-filter" method="get"><input class="form-control form-control-sm" name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="No. retur">
    <select class="form-select form-select-sm" name="status"><option value="">Semua</option><?php foreach (['DRAFT', 'SUBMITTED', 'APPROVED', 'POSTED', 'REJECTED', 'CANCELLED'] as $st): ?><option <?= ($_GET['status'] ?? '') === $st ? 'selected' : '' ?>><?= $st ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-secondary">Filter</button></form>
    <?php if (can('sales.return.create')): ?><a class="btn btn-sm btn-primary" href="<?= site_url('sales/returns/create') ?>" data-testid="srt-create-btn"><i class="bi bi-plus-lg me-1"></i>Retur Baru</a><?php endif; ?></div>
<div class="card erp-card"><table class="table table-sm table-hover erp-table mb-0" data-testid="srt-table"><thead><tr><th>No.</th><th>Tanggal</th><th>Pelanggan</th><th class="text-end">Nilai</th><th>Status</th></tr></thead><tbody>
<?php foreach ($page->items as $r): ?><tr data-testid="srt-row-<?= $r['id'] ?>"><td class="font-monospace small"><a href="<?= site_url('sales/returns/' . $r['id']) ?>"><?= e($r['doc_no']) ?></a></td><td class="small"><?= fmt_date($r['doc_date']) ?></td><td class="small"><?= e($r['customer_name'] ?: 'Umum') ?></td><td class="text-end"><?= fmt_idr($r['total_value']) ?></td><td><?= status_badge($r['status']) ?></td></tr><?php endforeach; ?>
<?php if (!$page->items): ?><tr><td colspan="5" class="text-center text-muted py-4">Belum ada retur</td></tr><?php endif; ?></tbody></table><div class="card-footer py-1"><?php $this->load->view('partials/pagination', ['page' => $page]); ?></div></div>
